"""Shared config for night-1 mapping runners: DB path, PII column-name patterns, jsonl helpers."""
import ast, json, os, re

BASE = "/Users/giladbarnea/clients-pii-hardening/avidor/meta/mapping/26-07-22-night1"
RAW_DB = "/Users/giladbarnea/clients-pii-hardening/avidor/world/pii-work/avidor.26-07-05.raw.duckdb"
REDACT_SRC = "/Users/giladbarnea/clients-pii-hardening/avidor/deploy/ingest/redact_pii.py"

_PII_LIST_NAMES = ["NATIONAL_ID", "CARD", "CRED", "NAME", "EMAIL_RE", "PHONE", "ADDRESS", "BIRTH", "RECORDING", "FREETEXT_ALWAYS", "FREETEXT_PERSON", "CITYSCRUB"]

def _load_pii_patterns() -> list[re.Pattern]:
    tree = ast.parse(open(REDACT_SRC).read())
    patterns: list[str] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Assign):
            continue
        for target in node.targets:
            if isinstance(target, ast.Name) and target.id in _PII_LIST_NAMES and isinstance(node.value, ast.List):
                for element in node.value.elts:
                    if isinstance(element, ast.Constant) and isinstance(element.value, str):
                        patterns.append(element.value)
    assert len(patterns) > 80, f"expected >80 PII patterns, got {len(patterns)}"
    return [re.compile(p, re.I) for p in patterns]

PII_PATTERNS = _load_pii_patterns()

def is_pii_named(column: str) -> bool:
    low = column.lower()
    return any(p.search(low) for p in PII_PATTERNS)

def connect(memory_limit: str = "3GB", threads: int = 4):
    import duckdb
    con = duckdb.connect(RAW_DB, read_only=True)
    con.execute(f"SET memory_limit='{memory_limit}'")
    con.execute(f"SET threads={threads}")
    os.makedirs(os.path.join(BASE, "lane1", "tmp"), exist_ok=True)
    con.execute(f"SET temp_directory='{os.path.join(BASE, 'lane1', 'tmp')}'")
    return con

def append_jsonl(path: str, obj) -> None:
    with open(path, "a") as f:
        f.write(json.dumps(obj, ensure_ascii=False, default=str) + "\n")

def load_jsonl(path: str) -> list:
    if not os.path.exists(path):
        return []
    return [json.loads(line) for line in open(path) if line.strip()]

